<?php declare(strict_types=1); namespace App\Services\Admin; use App\Models\Employee; use App\Repositories\EmployeeRepository; use Illuminate\Pagination\LengthAwarePaginator; use Illuminate\Support\Facades\DB;
final class EmployeeService { public function __construct(private EmployeeRepository $repo){} public function paginate(array $f=[],int $per=15): LengthAwarePaginator { return $this->repo->paginateForAdmin($f,$per);} public function store(array $d): Employee { return DB::transaction(fn()=>$this->repo->create($d)); } public function update(Employee $e,array $d): Employee { return DB::transaction(fn()=>$this->repo->update($e,$d)); } public function findOrFail(int $id): Employee { return $this->repo->findOneOrFail($id,['department','user']); }}